import{_ as a,o as r,c as t,a3 as l}from"./chunks/framework.BLKCyc-R.js";const c=JSON.parse('{"title":"API reference","description":"","frontmatter":{},"headers":[],"relativePath":"api/index.md","filePath":"api/index.md"}'),i={name:"api/index.md"};function n(s,e,o,d,p,h){return r(),t("div",null,[...e[0]||(e[0]=[l('<h1 id="api-reference" tabindex="-1">API reference <a class="header-anchor" href="#api-reference" aria-label="Permalink to &quot;API reference&quot;">​</a></h1><p>The reference of every public symbol of <code>@sakuzu/maplibre-gl-draw</code>, generated from the sources. To learn how to use the library, start with <a href="/maplibre-gl-draw/getting-started.html">Getting started</a> and the guides.</p><h2 id="where-to-start" tabindex="-1">Where to start <a class="header-anchor" href="#where-to-start" aria-label="Permalink to &quot;Where to start&quot;">​</a></h2><ul><li>To put a drawing on a map, start from <a href="/maplibre-gl-draw/api/maplibre-gl-draw/functions/createDraw.html">createDraw</a> and its <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/DrawOptions.html">DrawOptions</a>.</li><li>To add, change and remove features, layers and groups, use the collections of the instance, <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/Draw.html">Draw</a>. Its page is grouped by task.</li><li>A <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/Feature.html">Feature</a>, a <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/Layer.html">Layer</a> and a <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/Group.html">Group</a> are the data model.</li><li>To react to changes and clicks, see the events of <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/DrawEvents.html">DrawEvents</a>.</li><li>To style features, see <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/FeatureStyle.html">FeatureStyle</a> and <a href="/maplibre-gl-draw/api/maplibre-gl-draw/type-aliases/StyleRule.html">StyleRule</a>.</li><li>To show large data that is not edited, see <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/Dataset.html">Dataset</a> and <a href="/maplibre-gl-draw/api/maplibre-gl-draw/type-aliases/DatasetOptions.html">DatasetOptions</a>.</li><li>To save and load, see <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/DrawDocument.html">DrawDocument</a> and <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/LoadOptions.html">LoadOptions</a>.</li><li>To add a plugin, a mode or a feature type, see <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/Plugin.html">Plugin</a>, <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/ModeHandler.html">ModeHandler</a> and <a href="/maplibre-gl-draw/api/maplibre-gl-draw/interfaces/FeatureTypeDefinition.html">FeatureTypeDefinition</a>.</li></ul><h2 id="entry-points" tabindex="-1">Entry points <a class="header-anchor" href="#entry-points" aria-label="Permalink to &quot;Entry points&quot;">​</a></h2><p>The package has four entry points. Import from the first one unless you need the others.</p><ul><li><code>@sakuzu/maplibre-gl-draw</code> (<a href="/maplibre-gl-draw/api/maplibre-gl-draw/">the reference</a>): the instance, its options, the data model, the events, datasets and the extension contract.</li><li><code>@sakuzu/maplibre-gl-draw/geometry</code> (<a href="/maplibre-gl-draw/api/geometry/">the reference</a>): geometry calculations that need no map: measure lengths and areas, build circles and buffers, combine polygons, test whether a point lies in a polygon, and tidy shapes. They also work in code that does not use the drawing engine (workers, servers, tests).</li><li><code>@sakuzu/maplibre-gl-draw/table</code> (<a href="/maplibre-gl-draw/api/table/">the reference</a>): the parts for reading a large table in a Worker and putting it on the map as a dataset.</li><li><code>@sakuzu/maplibre-gl-draw/webgl</code> (<a href="/maplibre-gl-draw/api/webgl/">the reference</a>): building blocks for custom shaders. They may change in a minor release; everything else follows semantic versioning.</li></ul>',7)])])}const g=a(i,[["render",n]]);export{c as __pageData,g as default};
